    /** Bounded cursor used only for the envelope, never for frame interpretation. */
    private static final class HeaderCursor {
        final byte[] wire;
        int pos;
        HeaderCursor(byte[] wire, int offset) { this.wire=wire; pos=offset; }
        int remaining() { return wire.length-pos; }
        int octet() { require(remaining()>0, "BAD_HEADER"); return wire[pos++] & 255; }
        byte[] bytes(long n) {
            require(n>=0 && n<=remaining(), "BAD_HEADER");
            byte[] b=Arrays.copyOfRange(wire,pos,pos+(int)n); pos+=(int)n; return b;
        }
        long raw(int n) { long v=0; for (int i=0;i<n;i++) v=(v<<8)|octet(); return v; }
        long integer() {
