            require((first>=0xc0 && first<=0xc3)||(first>=0xe0 && first<=0xe3),"BAD_HEADER");
            p.level=first<0xe0?"I":"H";
            require(c.raw(4)==1,"BAD_HEADER");
            int n=c.octet(); require(n<=20,"BAD_HEADER"); p.destination=c.bytes(n);
            n=c.octet(); require(n<=20,"BAD_HEADER"); p.source=c.bytes(n);
            p.token=p.level.equals("I")?c.bytes(c.integer()):new byte[0];
            long length=c.integer();
            require(length>=p.numberLength && length<=c.remaining(),"BAD_HEADER");
            p.end=c.pos+(int)length;
            p.truncated=c.raw(p.numberLength);
            p.payload=c.bytes(length-p.numberLength);
        } else {
            require((first&0x40)!=0 && (first&0x18)==0,"BAD_HEADER");
            p.level="A"; p.phase=(first>>>2)&1;
            p.destination=c.bytes(config.localCids.get(0).length);
