    /** Nearest nonnegative representative; the upper representative wins a tie. */
    private static long reconstruct(long raw, int width, long expected) {
        long window=1L << (width*8), half=window/2;
        long pn=(expected & ~(window-1)) | raw;
        if (pn<expected && expected-pn>=half) pn+=window;
        else if (pn>expected && pn-expected>half && pn>=window) pn-=window;
        return pn;
    }
    private byte[] canonical(Main.Packet p, byte[] body, long expected) {
        int width=1;
        while (width<4 && reconstruct(p.pn & ((1L<<(8*width))-1),width,expected)!=p.pn) width++;
        ByteArrayOutputStream out=new ByteArrayOutputStream();
        if (p.level.equals("A")) {
            out.write(0x40|(p.phase<<2)|(width-1)); append(out,p.destination);
        } else {
            out.write((p.level.equals("I")?0xc0:0xe0)|(width-1));
            append(out,new byte[]{0,0,0,1});
            out.write(p.destination.length); append(out,p.destination);
            out.write(p.source.length); append(out,p.source);
            if (p.level.equals("I")) { varint(out,p.token.length); append(out,p.token); }
            varint(out,width+(long)body.length);
