    /** Nonoverlapping immutable byte pieces. Addresses never determine array allocations. */
    private static final class Sparse {
        final TreeMap<Long,byte[]> pieces=new TreeMap<>();
        void add(long offset, byte[] data, Transaction tx) {
            long end=offset+data.length, at=offset;
            while (at<end) {
                Map.Entry<Long,byte[]> e=pieces.floorEntry(at);
                if (e!=null && e.getKey()+e.getValue().length>at) {
                    long until=Math.min(end,e.getKey()+e.getValue().length);
                    byte[] previous=e.getValue();
                    for (long i=at;i<until;i++) {
                        require(data[(int)(i-offset)]==previous[(int)(i-e.getKey())],"PROTOCOL_VIOLATION");
                    }
                    at=until;
                } else {
                    e=pieces.ceilingEntry(at);
                    long until=e==null?end:Math.min(end,e.getKey());
                    final long key=at;
                    pieces.put(key,Arrays.copyOfRange(data,(int)(at-offset),(int)(until-offset)));
                    tx.undo.add(() -> pieces.remove(key));
