    }

    /** Metadata uses copy-on-write; sparse inserts and registry changes have an undo journal.
     * ACKs and epochs are validated now but only applied at commit. */
    private final class Transaction {
        final long oldUsed=used, oldBidi=openedBidi, oldUni=openedUni, oldSend=sendData,
            oldSendBidi=sendBidi, oldSendUni=sendUni, oldThreshold=threshold;
        final List<Runnable> undo=new ArrayList<>();
        final Set<Long> touched=new HashSet<>();
        final List<AckFrame> pendingAcks=new ArrayList<>();
        Stream touch(long id) {
            if (touched.add(id)) {
                Stream old=streams.get(id);
                undo.add(() -> { if(old==null) streams.remove(id); else streams.put(id,old); });
                streams.put(id,old==null?new Stream():new Stream(old));
            }
            return streams.get(id);
        }
        void rollback() {
            for (int i=undo.size()-1;i>=0;i--) undo.get(i).run();
            used=oldUsed; openedBidi=oldBidi; openedUni=oldUni; sendData=oldSend;
            sendBidi=oldSendBidi; sendUni=oldSendUni; threshold=oldThreshold;
        }
        void commit(int level) { for(AckFrame f:pendingAcks) acks[level].commit(f); }
    }

    private Stream reference(long id, boolean receive, Transaction tx) {
        int kind=(int)(id&3); long index=id/4;
        if (receive) require(kind!=3,"STREAM_STATE_ERROR");
        else require(kind!=2,"STREAM_STATE_ERROR");
        if (kind==1 || kind==3) {
            require(index<(kind==1?config.localBidi:config.localUni),"STREAM_STATE_ERROR");
        } else {
            require(index<(kind==0?config.bidi:config.uni),"STREAM_LIMIT_ERROR");
            if (kind==0) openedBidi=Math.max(openedBidi,index+1);
            else openedUni=Math.max(openedUni,index+1);
        }
        return tx.touch(id);
    }
    private void credit(Stream s,long high) {
        long candidate=used+(high-s.high);
        require(high<=config.stream && candidate<=config.connection,"FLOW_CONTROL_ERROR");
        used=candidate; s.high=high;
    }
    private static void validateAck(AckFrame f) {
        long largest=f.getLargestAcknowledged().getValue(), first=f.getFirstACKRange().getValue();
        encoding(first<=largest); long low=largest-first;
        long[] pairs=f.getRangePairs();
        for (int i=0;i<pairs.length;i+=2) {
            long gap=pairs[i], range=pairs[i+1];
            encoding(low>=gap+2); long high=low-gap-2;
            encoding(range<=high); low=high-range;
        }
    }
    private void newCid(NewConnectionIdFrame f, Transaction tx) {
