        encoding(f.getConnectionIdLength().getValue()>=1 && f.getConnectionIdLength().getValue()<=20 && retire<=sequence);
        PeerCid candidate=new PeerCid(sequence,f.getConnectionId().getValue(),f.getStatelessResetToken().getValue());
        PeerCid old=peerHistory.get(sequence);
        require(old==null || (old.id.equals(candidate.id)&&old.token.equals(candidate.token)),"PROTOCOL_VIOLATION");
        Long owner=peerOwners.get(candidate.id);
        require(owner==null || owner.longValue()==sequence,"PROTOCOL_VIOLATION");
        if (old==null) {
            peerHistory.put(sequence,candidate); peerOwners.put(candidate.id,sequence);
            tx.undo.add(() -> { peerHistory.remove(sequence); peerOwners.remove(candidate.id); });
        }
