        while (!activePeer.isEmpty() && activePeer.firstKey()<threshold) {
            Map.Entry<Long,PeerCid> removed=activePeer.pollFirstEntry();
            tx.undo.add(() -> activePeer.put(removed.getKey(),removed.getValue()));
