                s.sendMax=Math.max(s.sendMax,f.getMaximumStreamData().getValue()); return;
            }
            case 18: case 19: {
                long maximum=((MaxStreamsFrame)frame).getMaximumStreams().getValue(); encoding(maximum<=1L<<60);
                if(type==18) sendBidi=Math.max(sendBidi,maximum); else sendUni=Math.max(sendUni,maximum); return;
            }
