    private static final class FrameResult {
        String status="OK"; int offset; byte[] canonical;
    }
    private FrameResult frames(Main.Packet packet,int level,Transaction tx) {
        FrameResult result=new FrameResult(); ByteArrayInputStream in=new ByteArrayInputStream(packet.payload);
        ByteArrayOutputStream out=new ByteArrayOutputStream(); int at=0;
        try {
            encoding(in.available()>0);
            while(in.available()>0) {
                at=packet.payload.length-in.available();
                int before=in.available();
                long value;
                try { value=VariableLengthIntegerEncoding.readVariableLengthInteger(in); }
                catch(IOException e) { throw new Failure("FRAME_ENCODING_ERROR"); }
                int typeLength=before-in.available();
                encoding(typeLength==VariableLengthIntegerEncoding.encodeVariableLengthInteger(value).length);
                QuicFrame f=QuicFrameLayer.create(value); encoding(f!=null);
                int type=(int)value;
                boolean common=type<=3 || type==6 || type==28;
                require(type!=7 && type!=30 && (level==2 || common),"PROTOCOL_VIOLATION");
                f.getParser(in).parse(f);
                apply(f,type,level,packet,tx);
                append(out,f.getSerializer().serialize());
                if(type==28 || type==29) { result.status="PEER_CLOSE"; result.offset=at; break; }
            }
            result.canonical=out.toByteArray();
        } catch(Failure e) {
            result.status=e.code; result.offset=at; tx.rollback();
        } catch(ParserException|EndOfStreamException e) {
            result.status="FRAME_ENCODING_ERROR"; result.offset=at; tx.rollback();
        }
        return result;
    }

    private String admission(Main.Packet p,int level,Long annotation) {
        if(closed!=null) return "CLOSED";
        if(p.dcid==null || retired[p.dcid.intValue()]) return "DROP_CID";
        if(!keys[level]) return "NO_KEY";
        if(p.pn>MAX) return "PN_RANGE";
        if(level!=2) {
            if(annotation==null || annotation!=0) return "AUTH";
        } else {
            if(annotation==null || annotation<Math.max(0,epoch-1) || annotation>Math.min(MAX,epoch+1)
                    || (annotation&1)!=p.phase) return "AUTH";
            p.generation=annotation;
        }
        if(seen.get(level).contains(p.pn)) return "DUPLICATE";
        if(level==2) {
            Map.Entry<Long,Epoch> lower=epochs.lowerEntry(annotation), higher=epochs.higherEntry(annotation);
            if((lower!=null && lower.getValue().max>=p.pn)||(higher!=null && higher.getValue().min<=p.pn)) return "KEY_UPDATE_ERROR";
        }
        return "OK";
    }
    private void accept(Main.Packet p,int level) {
        seen.get(level).add(p.pn); largest[level]=Math.max(largest[level],p.pn);
        if(level==2) {
            Epoch stats=epochs.get(p.generation);
            if(stats==null) epochs.put(p.generation,new Epoch(p.pn)); else stats.add(p.pn);
            epoch=Math.max(epoch,p.generation);
        }
    }
    private void datagram(Main.Event e,int event) {
        int offset=0, number=0, accepted=0; long bytes=0; MessageDigest d=digest();
        while(offset<e.wire.length) {
            Main.Packet p;
            try { p=header(e.wire,offset); }
            catch(Failure failure) {
                packets.add(object("event",event,"packet",number,"offset",offset,"level",null,"pn",null,
                    "epoch",null,"status","BAD_HEADER","sha256",null)); number++; break;
            }
            int level=p.level.equals("I")?0:p.level.equals("H")?1:2;
            long expected=largest[level]+1;
            p.pn=reconstruct(p.truncated,p.numberLength,expected);
            Long annotation=number<e.auth.size()?e.auth.get(number):null;
            String status=admission(p,level,annotation), sha=null;
            int closeOffset=0;
            if(status.equals("OK")) {
                Transaction tx=new Transaction(); FrameResult f=frames(p,level,tx); status=f.status; closeOffset=f.offset;
                if(status.equals("OK")||status.equals("PEER_CLOSE")) {
                    tx.commit(level); accept(p,level);
                    byte[] canon=canonical(p,f.canonical,expected); sha=hash(canon);
                    d.update(canon); bytes+=canon.length; accepted++;
                }
            }
            if(status.equals("KEY_UPDATE_ERROR") || status.equals("PEER_CLOSE") ||
                    status.endsWith("_ERROR") || status.equals("PROTOCOL_VIOLATION")) {
                closed=object("event",event,"packet",number,"offset",closeOffset,"code",status);
            }
            packets.add(object("event",event,"packet",number,"offset",offset,"level",p.level,"pn",p.pn,
                "epoch",p.generation,"status",status,"sha256",sha));
            offset=p.end; number++;
        }
        datagrams.add(object("event",event,"packets",number,"accepted",accepted,"bytes",bytes,"sha256",Main.hex(d.digest())));
    }

    public Map<String,Object> audit(Main.Trace trace) {
        config=trace; largest=trace.received.clone(); retired=new boolean[trace.localCids.size()];
        for(int i=0;i<retired.length;i++) localOwners.put(Main.hex(trace.localCids.get(i)),(long)i);
        PeerCid initial=new PeerCid(0,trace.peerCid,trace.peerToken);
        peerHistory.put(0L,initial); activePeer.put(0L,initial); peerOwners.put(initial.id,0L);
        for(int i=0;i<3;i++) if(largest[i]>=0) seen.get(i).add(largest[i]);
        if(largest[2]>=0) epochs.put(0L,new Epoch(largest[2]));
